/**
 * Golden contract for the SM-18 format-read port follow-up on `.sub` files
 * (sm18-re gitlab #42).
 *
 * Follow-up to #36. The two glob families (`info/*.sub`, `subsets/*.sub`)
 * share one record layout — one little-endian `u32` element id per entry,
 * no header, no trailer — but the `info/` family carries list-kind semantics
 * (`smfmt.info_subs.KINDS`) that `subsets/` does not.
 *
 * The fixture `test/fixtures/sm18-port-format-read-sub.json` is a mirror of
 * `sm18-re:tests/fixtures/port-format-read-sub.json`, regenerated by
 * `sm18-re:scripts/export-port-format-read-sub-fixture.py` on the ABC
 * collection. Re-copy on every fixture change so sm18-re's gate catches
 * drift on either side.
 *
 * This file is brief-writer owned. The lane adds, additively, to
 * `src/sm18-format-read.ts`:
 *
 *   parseSub(bytes: Uint8Array): number[]
 *   subKind(name: string): string | null
 *   queuePositions(bytes: Uint8Array): Map<number, number>
 *   HISTORY_CAP: number
 *
 * - `parseSub` is a decoder, not a resolver — it returns element ids in
 *   stored order. A byte length that is not a multiple of 4 is an error.
 * - `subKind` resolves a filename against the `KINDS` table from
 *   `smfmt/info_subs.py`. Matching is case-insensitive (SuperMemo writes
 *   `history.sub` but `OutstandingItems.sub`). Accepts a bare name, a stem,
 *   or a whole path. Returns `null` for a name not in the table — the port
 *   must not invent kinds for `subsets/*.sub` names.
 * - `queuePositions` mirrors `info_subs.queue_positions`: preserves stored
 *   order (0-based position), throws on repeated ids. A `Map` is the shape
 *   the brief specifies; the port must not degrade this to a plain object or
 *   a set.
 * - `HISTORY_CAP` is an exported constant whose value matches the fixture's
 *   `history_cap` field. Its caveat (observation across the Cyber-family
 *   copies, not a constant read from the executable) belongs in the TS doc
 *   comment on the export.
 *
 * The element ids are 1-based indices into `info/ElementInfo.dat`. The port
 * does NOT resolve them against `parseElementInfo` on this lane; that
 * composition belongs to a later element-browser / queue lane.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-read-sub.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-read.ts"].join("/");

interface QueuePositionEntry {
  element_id: number;
  position: number;
}

interface FixtureFile {
  path: string;
  byte_length: number;
  bytes_b64: string;
  record_count: number;
  element_ids: number[];
  kind: string | null;
  queue_positions: QueuePositionEntry[] | null;
}

interface Fixture {
  schema: number;
  collection: string;
  scope: string[];
  history_cap: number;
  files: FixtureFile[];
}

interface PortModule {
  parseSub: (bytes: Uint8Array) => number[];
  subKind: (name: string) => string | null;
  queuePositions: (bytes: Uint8Array) => Map<number, number>;
  HISTORY_CAP: number;
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (
      typeof mod?.parseSub !== "function" ||
      typeof mod?.subKind !== "function" ||
      typeof mod?.queuePositions !== "function" ||
      typeof mod?.HISTORY_CAP !== "number"
    ) {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the sub scope and non-empty files", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["sub"]);
  assert.ok(fixture.files.length > 0);
  assert.equal(typeof fixture.history_cap, "number");
  for (const file of fixture.files) {
    assert.equal(
      file.byte_length % 4,
      0,
      `${file.path} byte length must be a multiple of 4`,
    );
    assert.equal(file.record_count * 4, file.byte_length);
    assert.equal(file.element_ids.length, file.record_count);
  }
});

test("src/sm18-format-read.ts exports parseSub/subKind/queuePositions/HISTORY_CAP", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("sub-family exports not implemented yet");
    return;
  }
  assert.equal(typeof port.parseSub, "function");
  assert.equal(typeof port.subKind, "function");
  assert.equal(typeof port.queuePositions, "function");
  assert.equal(typeof port.HISTORY_CAP, "number");
});

test("HISTORY_CAP matches the fixture value", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("HISTORY_CAP not implemented yet");
    return;
  }
  assert.equal(port.HISTORY_CAP, fixture.history_cap);
});

test("parseSub throws on a byte length not a multiple of 4", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseSub not implemented yet");
    return;
  }
  const partial = new Uint8Array([1, 2, 3]);
  assert.throws(() => port.parseSub(partial));
});

for (const file of fixture.files) {
  test(`format-read-sub: ${file.path} parses to ${file.record_count} ids`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("parseSub not implemented yet");
      return;
    }
    const bytes = decodeBase64(file.bytes_b64);
    assert.equal(
      bytes.byteLength,
      file.byte_length,
      `byte count for ${file.path}`,
    );
    const parsed = port.parseSub(bytes);
    assert.deepEqual(parsed, file.element_ids);
  });

  test(`format-read-sub: ${file.path} subKind resolution`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("subKind not implemented yet");
      return;
    }
    const name = file.path.replace(/^.*\//, "");
    assert.equal(
      port.subKind(name),
      file.kind,
      `subKind(${name}) must match the fixture`,
    );
    assert.equal(
      port.subKind(file.path),
      file.kind,
      `subKind(${file.path}) must match the fixture (path form)`,
    );
    const stem = name.replace(/\.sub$/i, "");
    assert.equal(
      port.subKind(stem),
      file.kind,
      `subKind(${stem}) must match the fixture (stem form)`,
    );
  });

  if (file.queue_positions !== null) {
    test(`format-read-sub: ${file.path} queuePositions`, async (t) => {
      const port = await loadPort();
      if (port === null) {
        t.skip("queuePositions not implemented yet");
        return;
      }
      const bytes = decodeBase64(file.bytes_b64);
      const positions = port.queuePositions(bytes);
      assert.ok(positions instanceof Map, "queuePositions must return a Map");
      assert.equal(positions.size, file.queue_positions.length);
      for (const entry of file.queue_positions) {
        assert.equal(
          positions.get(entry.element_id),
          entry.position,
          `position for ${entry.element_id} in ${file.path}`,
        );
      }
    });
  }
}
